class Todo:
    def __init__(self, task):
        self.task = task
        self.done = False

class TodoManager:
    def __init__(self):
        self.todos = []

    def add(self, task):
        self.todos.append(Todo(task))

    def complete(self, task_name):
        for todo in self.todos:
            if todo.task == task_name:
                todo.done = True

